import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("Files in archive:")
for n in z.namelist():
    print(" ", n)
print()

wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
rels_xml = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))

rel_map = {}
for rel in rels_xml:
    rel_map[rel.get("Id")] = rel.get("Target")

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in ss.findall("m:si", NS):
        shared.append("".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")))

def col_to_idx(ref):
    col = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in col:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

for sheet in wb_xml.find("m:sheets", NS):
    name = sheet.get("name")
    rid = sheet.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    target = rel_map[rid]
    if not target.startswith("xl/"):
        target = "xl/" + target
    print(f"=== Sheet: {name} ({target}) ===")
    sx = ET.fromstring(z.read(target))
    for row in sx.iter("m:row", NS):
        rnum = row.get("r")
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            val = None
            if v is not None:
                if t == "s":
                    val = shared[int(v.text)]
                elif t == "inlineStr":
                    is_el = c.find("m:is", NS)
                    val = "".join(tt.text or "" for tt in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                else:
                    val = v.text
            if val is not None:
                print(f"  {ref} = {val!r}")
    print()

