import zipfile
import xml.etree.ElementTree as ET

T = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
z = zipfile.ZipFile("budget.xlsx")
sx = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

# Row -> (category, subcategory, amount)
expenses = []
incomes = []
for row in sx.iter(T + "row"):
    cells = {}
    for c in row.findall(T + "c"):
        ref = c.get("r")
        v = c.find(T + "v")
        if v is not None:
            if c.get("t") == "inlineStr":
                is_el = c.find(T + "is")
                cells[ref[-1]] = "".join(tt.text or "" for tt in is_el.iter(T + "t"))
            else:
                cells[ref[-1]] = float(v.text)
    r = int(row.get("r"))
    if r == 0:
        continue
    if 11 <= r <= 22 and "C" in cells:
        expenses.append((cells.get("A", "?"), cells.get("B", "?"), cells["C"]))
    if 4 <= r <= 7 and "B" in cells:
        incomes.append((cells.get("A", "?"), cells["B"]))

print("Income:")
for name, amt in incomes:
    print(f"  {name}: {amt:,.2f}")
print(f"  TOTAL (B4:B7): {sum(a for _, a in incomes):,.2f}")
print()
print("Expenses by category:")
by_cat = {}
for cat, sub, amt in expenses:
    by_cat.setdefault(cat, []).append((sub, amt))
grand = 0.0
for cat in by_cat:
    subtotal = sum(a for _, a in by_cat[cat])
    grand += subtotal
    print(f"  {cat}:")
    for sub, amt in by_cat[cat]:
        print(f"    {sub}: {amt:,.2f}")
    print(f"    Subtotal: {subtotal:,.2f}")
print(f"\nTOTAL EXPENSES (C11:C22): {grand:,.2f}")

